item.content:encoded:
/*
You can add your own CSS here.

Click the help icon above to learn more.
*/


.widget_sp_image a{
	opacity:1;
}

.widget_sp_image img{
	width:100%;
}

.widget_sp_image-description{
	margin-top:10px;
}

.views-meta,
.likes-meta{
	display:none!important;
}

.plugin-details .item-icon{
	display:none;
}

[data-item-slug="firemaster"]:before {
    content: 'FEATURED'!important;
    text-transform: uppercase;
    font-weight: 700;
    text-align: center;
    background: #00DB8A!important;
    position: absolute;
    z-index: 99;
    border-radius: 0;
    left: 20px;
    top: 20px;
    padding: 5px 20px;
    width: auto;
    height: auto;
    line-height: 35px;
    font-size: 15px;
    color: #FFF;
    -webkit-backface-visibility: hidden;
    backface-visibility: hidden;
}

/* Hide animated top bar */
body:not(.postid-159) #wolf-message-bar-container,
.music-social-icons-container{
	display:none;
}

#plugins-content .plugin-title {
    font-size: 24px;
    -webkit-transition: all .2 ease;
	transition: all .2s ease;
}

.single-plugin .dashicons-download,
.single-plugin .single-post-taxonomy-container,
.single-plugin .single-post-bottom-line,
.item-downloads-count{
	display:none;
}

.single-plugin .entry-content{
		max-width: 750px;
    margin: 0 auto;
}

.envato-item-buttons a{
	border-radius:4px;
}

.spinner{
	display:none!important;
}

.logo-svg{
	margin-top:-10px
}

body{
	font-size:18px;
}

.button--skoll{
	font-size:14px;
}

.single-post .wolf-core-mailchimp-form-container{
	border:none;
	margin:0;
}

@media screen and (min-width: 800px) {
    .wolf-core-testimonal-slide blockquote {
        font-size: 28px;
    }
}

/* Fix ion on non Elementor page */
.elementor-icon{
	display
}
	.wolf-core-pricing-table-header{
		flex-direction:column;
		text-align:left;
		align-items: flex-start;
	}

.wolf-core-pricing-table-title{
	font-size:14px;
}

.wolf-core-pricing-table-price-value{
	font-size:48px;
}

.wolf-core-pricing-table-content{
	font-size:16px;
}

.wolf-core-pricing-table-inner{
	padding:60px 50px
}

.logo{
	position:relative;
	top:-5px;
}

.logo{
	position:relative;
	top:-10px;
}

.single-wolf_theme #breadcrumb-header{
	display:none;
}

.logo{
	position:relative;
	top:-10px;
}

.single-wolf_theme #breadcrumb-header{
	display:none;
}

